import express from 'express';
import cors from 'cors';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 8321;

app.use(cors());
app.use(express.json());

// Generate 50 mock items
const mockItems = [];
for (let i = 1; i <= 50; i++) {
  // Deterministic but non-sorted values to make sorting visible
  const value = 100 + ((i * 37) % 49) * 100;
  mockItems.push({
    id: i,
    name: `Item ${i}`,
    value: value,
  });
}

// API Endpoint
app.get('/api/data', (req, res) => {
  const page = parseInt(req.query.page, 10) || 1;
  const limit = parseInt(req.query.limit, 10) || 10;
  const sortBy = req.query.sortBy || 'id';
  const sortDesc = req.query.sortDesc === 'true';

  // Create a copy of mockItems to sort
  let sortedItems = [...mockItems];

  // Sort logic
  sortedItems.sort((a, b) => {
    let valA = a[sortBy];
    let valB = b[sortBy];

    if (valA === undefined) valA = a.id;
    if (valB === undefined) valB = b.id;

    if (typeof valA === 'string' && typeof valB === 'string') {
      return sortDesc
        ? valB.localeCompare(valA)
        : valA.localeCompare(valB);
    } else {
      // Numerical sort
      return sortDesc
        ? (valB - valA)
        : (valA - valB);
    }
  });

  // Pagination logic
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedItems = sortedItems.slice(startIndex, endIndex);

  res.json({
    data: paginatedItems,
    totalCount: mockItems.length,
  });
});

// Serve frontend static files in production
app.use(express.static(path.join(__dirname, 'dist')));

// Fallback to index.html for SPA routing
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000,
    proxy: {
      '/api': 'http://localhost:8321',
    },
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: light dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #242424;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  display: flex;
  justify-content: center;
  min-width: 320px;
  min-height: 100vh;
}

#root {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
  width: 100%;
}

h1 {
  font-size: 2.5rem;
  margin-bottom: 2rem;
  color: #646cff;
}

.table-container {
  background-color: #1a1a1a;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

th, td {
  padding: 12px 16px;
  border-bottom: 1px solid #333;
}

th {
  background-color: #2a2a2a;
  font-weight: 600;
  color: #e2e8f0;
  cursor: pointer;
  user-select: none;
  transition: background-color 0.2s;
}

th:hover {
  background-color: #3a3a3a;
}

tr:hover {
  background-color: #222;
}

.sort-icon {
  margin-left: 8px;
  display: inline-block;
  color: #646cff;
}

.pagination-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 1.5rem;
}

.pagination-info {
  font-size: 0.9rem;
  color: #a0aec0;
}

.pagination-buttons {
  display: flex;
  gap: 10px;
}

button {
  border-radius: 6px;
  border: 1px solid transparent;
  padding: 0.6em 1.2em;
  font-size: 0.9rem;
  font-weight: 500;
  font-family: inherit;
  background-color: #1a1a1a;
  color: #e2e8f0;
  border: 1px solid #444;
  cursor: pointer;
  transition: border-color 0.25s, background-color 0.25s;
}

button:hover:not(:disabled) {
  border-color: #646cff;
  background-color: #2a2a2a;
}

button:active:not(:disabled) {
  background-color: #333;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.loading {
  font-size: 1.2rem;
  color: #a0aec0;
  margin: 2rem 0;
}

.error-message {
  color: #fc8181;
  background-color: rgba(252, 129, 129, 0.1);
  padding: 1rem;
  border-radius: 6px;
  border: 1px solid #fc8181;
  margin-bottom: 1.5rem;
}

/* Light mode overrides if system prefers */
@media (prefers-color-scheme: light) {
  :root {
    color: #213547;
    background-color: #f7fafc;
  }

  .table-container {
    background-color: #ffffff;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
  }

  th {
    background-color: #edf2f7;
    color: #2d3748;
    border-bottom: 2px solid #e2e8f0;
  }

  th:hover {
    background-color: #e2e8f0;
  }

  td {
    border-bottom: 1px solid #e2e8f0;
  }

  tr:hover {
    background-color: #f8fafc;
  }

  button {
    background-color: #ffffff;
    color: #2d3748;
    border: 1px solid #cbd5e0;
  }

  button:hover:not(:disabled) {
    background-color: #f7fafc;
    border-color: #646cff;
  }

  .pagination-info {
    color: #4a5568;
  }
}

import { useState, useEffect, useMemo } from 'react';
import {
  useReactTable,
  getCoreRowModel,
  ColumnDef,
  PaginationState,
  SortingState,
  flexRender,
} from '@tanstack/react-table';

interface Item {
  id: number;
  name: string;
  value: number;
}

export default function App() {
  const [data, setData] = useState<Item[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [sorting, setSorting] = useState<SortingState>([]);
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  });

  const columns = useMemo<ColumnDef<Item>[]>(
    () => [
      {
        accessorKey: 'id',
        header: 'ID',
      },
      {
        accessorKey: 'name',
        header: 'Name',
      },
      {
        accessorKey: 'value',
        header: 'Value',
      },
    ],
    []
  );

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const page = pagination.pageIndex + 1;
      const limit = pagination.pageSize;
      const sortBy = sorting[0]?.id || 'id';
      const sortDesc = sorting[0]?.desc ?? false;

      const url = `/api/data?page=${page}&limit=${limit}&sortBy=${sortBy}&sortDesc=${sortDesc}`;
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error('Failed to fetch data from server');
      }
      const result = await response.json();
      setData(result.data);
      setTotalCount(result.totalCount);
    } catch (err: any) {
      setError(err.message || 'An error occurred while fetching data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [pagination.pageIndex, pagination.pageSize, sorting]);

  const pageCount = Math.ceil(totalCount / pagination.pageSize);

  const table = useReactTable({
    data,
    columns,
    state: {
      pagination,
      sorting,
    },
    onPaginationChange: setPagination,
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    manualSorting: true,
    pageCount: pageCount,
  });

  return (
    <div>
      <h1>TanStack Table Server-Side Pagination & Sorting</h1>

      {error && <div className="error-message">{error}</div>}

      <div className="table-container">
        {loading ? (
          <div className="loading">Loading data...</div>
        ) : (
          <table>
            <thead>
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id}>
                  {headerGroup.headers.map((header) => {
                    const isSorted = header.column.getIsSorted();
                    return (
                      <th
                        key={header.id}
                        onClick={header.column.getToggleSortingHandler()}
                        style={{ cursor: 'pointer' }}
                      >
                        {flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                        {isSorted ? (
                          <span className="sort-icon">
                            {isSorted === 'desc' ? ' 🔽' : ' 🔼'}
                          </span>
                        ) : (
                          <span className="sort-icon" style={{ opacity: 0.2 }}>
                            {header.column.getCanSort() ? ' ↕️' : ''}
                          </span>
                        )}
                      </th>
                    );
                  })}
                </tr>
              ))}
            </thead>
            <tbody>
              {table.getRowModel().rows.map((row) => (
                <tr key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        )}

        <div className="pagination-container">
          <div className="pagination-info">
            Showing {pagination.pageIndex * pagination.pageSize + 1} to{' '}
            {Math.min((pagination.pageIndex + 1) * pagination.pageSize, totalCount)}{' '}
            of {totalCount} items (Page {pagination.pageIndex + 1} of {pageCount || 1})
          </div>
          <div className="pagination-buttons">
            <button
              onClick={() => table.previousPage()}
              disabled={!table.getCanPreviousPage() || loading}
            >
              Previous
            </button>
            <button
              onClick={() => table.nextPage()}
              disabled={!table.getCanNextPage() || loading}
            >
              Next
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
